def lucide(name: str, size: int = 18, color: str = "currentColor", stroke_width: float = 2.0, extra_class: str = "", style: str = "") -> str:
    """
    Returns an inline SVG for the requested Lucide icon.
    Matches standard Lucide specifications: 24x24 viewBox, stroke-based.
    """
    svg_body = LUCIDE_SVGS.get(name, LUCIDE_SVGS.get("help-circle"))
    combined_style = f"vertical-align: middle; display: inline-block; {style}".strip()
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" '
        f'fill="none" stroke="{color}" stroke-width="{stroke_width}" stroke-linecap="round" stroke-linejoin="round" '
        f'class="lucide lucide-{name} {extra_class}" style="{combined_style}">'
        f'{svg_body}'
        f'</svg>'
    )
